import json, pickle, time, sys
import numpy as np,cv2
from PIL import Image
from rcb_brush import MyPaintPainter,sheets_from_inst,Wells
from planner import resample,PX

def depth(radius):
 return np.clip(np.log(np.maximum(.4,2*radius*PX)/1.38)/.1875,.25,13.5)

def metrics(img):
 target=np.array(Image.open('/app/target.png'))
 for blur in [1,4]:
  aa=cv2.GaussianBlur(img.astype(np.float32)/255,(0,0),blur/PX)
  bb=cv2.GaussianBlur(target.astype(np.float32)/255,(0,0),blur/PX)
  lab_a=cv2.cvtColor(aa,cv2.COLOR_RGB2LAB);lab_b=cv2.cvtColor(bb,cv2.COLOR_RGB2LAB)
  de=np.linalg.norm(lab_a-lab_b,axis=2)
  a=lab_a[:,:,0];b=lab_b[:,:,0]
  ga=np.hypot(cv2.Sobel(a,-1,1,0),cv2.Sobel(a,-1,0,1));gb=np.hypot(cv2.Sobel(b,-1,1,0),cv2.Sobel(b,-1,0,1))
  print('blur',blur,'de mean',de.mean(),'p90',np.percentile(de,90),'edge',np.corrcoef(ga.ravel(),gb.ravel())[0,1],flush=True)
 return de

def render():
 inst=json.load(open('/app/instance.json'));p=MyPaintPainter(inst['brush'],sheets_from_inst(inst),Wells(inst['wells']));g=p.sheets['main'];R=np.diag([1.,-1.,-1.])
 paths=pickle.load(open('/app/output/paths.pkl','rb'));t=time.time()
 for j,stroke in enumerate(paths):
  path=resample(stroke['path'],.4/PX)
  if p.color!=stroke['color']:p._load(stroke['color']);p.loaded=True
  def sample(q,d):
   x,y=g.px_to_world(*q[:2]);p.sample([x,y,.02-d/1000],R)
  sample(path[0],-30)
  for d in np.linspace(-2,depth(path[0,2]),30):sample(path[0],d)
  for q in path:sample(q,depth(q[2]))
  for d in np.linspace(depth(path[-1,2]),-2,30):sample(path[-1],d)
  sample(path[-1],-30)
  if j%25==0:print(j,'/',len(paths),time.time()-t,flush=True)
 img=np.uint8(np.round(p.display()*255));Image.fromarray(img).save('/app/output/planned.png');np.save('/app/output/planned_ink.npy',p.display_ink());metrics(img)
if __name__=='__main__':render()
